// Draw marbles (simplified - just small rectangles)
const marbleSize = 18;
const marbleColors = ['#ff0000', '#0000ff', '#00ff00', '#ffff00', '#ff00ff', '#00ffff'];

// Randomly place marbles on the board
for (let i = 0; i < 12; i++) {
    const row = Math.floor(Math.random() * 8);
    const col = Math.floor(Math.random() * 8);
    const color = marbleColors[Math.floor(Math.random() * marbleColors.length)];

    // Check if the square is empty
    if ((row + col) % 2 === 0) {
        continue;
    }

    // Place marble
    const x = col * squareSize + (squareSize - marbleSize) / 2;
    const y = row * squareSize + (squareSize - marbleSize) / 2;
    ctx.fillStyle = color;
    ctx.fillRect(x, y, marbleSize, marbleSize);
}

// Draw some marble outlines
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
for (let i = 0; i < 4; i++) {
    const row = Math.floor(Math.random() * 8);
    const col = Math.floor(Math.random() * 8);
    const color = marbleColors[Math.floor(Math.random() * marbleColors.length)];

    // Check if the square is empty
    if ((row + col) % 2 === 0 || !marbleColors.includes(color)) {
        continue;
    }

    // Draw outline
    const x = col * squareSize + (squareSize - marbleSize) / 2;
    const y = row * squareSize + (squareSize - marbleSize) / 2;
    ctx.strokeRect(x, y, marbleSize, marbleSize);
}

