  const x1 = centerX + Math.cos(angle) * (maxRadius - 40);
  const y1 = centerY + Math.sin(angle) * (maxRadius - 40);

  const angle2 = ((i + 1) / 3) * Math.PI * 2;
  const x2 = centerX + Math.cos(angle2) * (maxRadius - 40);
  const y2 = centerY + Math.sin(angle2) * (maxRadius - 40);

  const angle3 = ((i + 2) / 3) * Math.PI * 2;
  const x3 = centerX + Math.cos(angle3) * (maxRadius - 40);
  const y3 = centerY + Math.sin(angle3) * (maxRadius - 40);

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.closePath();
  ctx.fill();
}

