// Draw shell spiral
ctx.fillStyle = '#808080';
ctx.beginPath();
ctx.moveTo(200, 250);
let radius = 10;
for(let i = 0; i < 12; i++) {
    let angle = (i / 12) * Math.PI * 2;
    let x = 200 + Math.cos(angle) * radius;
    let y = 250 + Math.sin(angle) * radius;
    if(i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    radius += 5;
}
ctx.closePath();
ctx.fill();

// Draw shell details
ctx.fillStyle = '#A9A9A9';
for(let i = 0; i < 12; i++) {
    let angle = (i / 12) * Math.PI * 2;
    let x = 200 + Math.cos(angle) * radius;
    let y = 250 + Math.sin(angle) * radius;
    ctx.fillRect(x - 2, y - 2, 4, 4);
}

